original_branding_logo_block:
{% block branding_logo %}
    <figure style="max-height: 120px;max-width: 120px;padding: 2px">
        <img src="{% static 'images/capcomposer_white.png' %}" alt="CAPComposer Dashboard Logo"
             style="height: 100%;width: 100%;object-fit: contain"/>
    </figure>
{% endblock %}

joint_branding_logo_block:
{% block branding_logo %}
    <figure style="max-height: 140px;max-width: 140px;padding: 2px">
        {% if che_composer_installed %}
            <img src="{% static 'images/cap_che_composer.png' %}"
                 alt="CAP and CHE Composer"
                 style="height: 100%;width: 100%;object-fit: contain"/>
        {% else %}
            <img src="{% static 'images/capcomposer_white.png' %}"
                 alt="CAP Composer"
                 style="height: 100%;width: 100%;object-fit: contain"/>
        {% endif %}
    </figure>
{% endblock %}
